def intersection_by_length(a, b):
    def length(node):
        n = 0
        while node:
            n += 1
            node = node.next
        return n

    la, lb = length(a), length(b)
    while la > lb:
        a = a.next
        la -= 1
    while lb > la:
        b = b.next
        lb -= 1
    while a is not b:
        a, b = a.next, b.next
    return a

def get_intersection_node(headA, headB):
    a, b = headA, headB
    while a is not b:
        a = a.next if a else headB
        b = b.next if b else headA
    return a
